content.css:
.atlyn-marimekko {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 6px;
  overflow: hidden;
  padding: 12px;
  color: var(--ink);
  background: var(--paper);
  font-family: "Segoe UI", system-ui, sans-serif;
  line-height: 1.35;
}
.atlyn-marimekko * {
  box-sizing: border-box;
}
.atlyn-marimekko > * {
  flex-shrink: 0;
  min-width: 0;
}
.atlyn-marimekko p,
.atlyn-marimekko h2 {
  margin: 0;
}
.atlyn-marimekko h2 {
  font-size: 15px;
}
.atlyn-marimekko .header,
.atlyn-marimekko .controls,
.atlyn-marimekko .legend,
.atlyn-marimekko .pager {
  display: flex;
  gap: 6px;
  align-items: center;
}
.atlyn-marimekko .header {
  justify-content: space-between;
}
.atlyn-marimekko .controls {
  flex-shrink: 0;
}
.atlyn-marimekko .title {
  font-size: 16px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.atlyn-marimekko button {
  font: inherit;
  color: inherit;
  background: var(--paper);
  border: 1px solid currentColor;
  border-radius: 4px;
  padding: 4px 8px;
  cursor: pointer;
  max-width: 100%;
  overflow-wrap: anywhere;
}
.atlyn-marimekko button[hidden] {
  display: none;
}
.atlyn-marimekko button:disabled {
  opacity: 0.55;
  cursor: default;
}
.atlyn-marimekko button:focus-visible,
.atlyn-marimekko [role="button"]:focus-visible,
.atlyn-marimekko [tabindex]:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 1px;
}
.atlyn-marimekko .encoding {
  font-size: 11px;
}
.atlyn-marimekko .status {
  max-height: 26%;
  overflow: auto;
  font-size: 11px;
}
.atlyn-marimekko .status:empty {
  display: none;
}
.atlyn-marimekko .diagnostic {
  border-inline-start: 3px solid currentColor;
  padding-inline-start: 6px;
  margin: 2px 0;
}
.atlyn-marimekko .denominator,
.atlyn-marimekko .total {
  font-weight: 600;
}
.atlyn-marimekko .total {
  font-size: 12px;
}
.atlyn-marimekko .legend {
  flex-wrap: wrap;
  max-height: 70px;
  overflow: auto;
  padding: 2px;
  gap: 4px 10px;
}
.atlyn-marimekko .legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  text-align: start;
  border: none;
  padding: 3px 2px;
  min-height: 28px;
}
.atlyn-marimekko .legend-item span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 220px;
}
.atlyn-marimekko .legend-caption {
  font-size: 11px;
  opacity: 0.85;
  flex-shrink: 0;
}
.atlyn-marimekko .legend-share {
  font-weight: 600;
}
.atlyn-marimekko .swatch {
  width: 12px;
  height: 12px;
  flex: 0 0 12px;
  border: 1px solid currentColor;
}
.atlyn-marimekko .plot-container {
  flex: 1 1 0;
  min-height: 0;
}
.atlyn-marimekko .chart {
  display: block;
  overflow: visible;
  font: inherit;
}
.atlyn-marimekko .cell,
.atlyn-marimekko .segment-label {
  cursor: pointer;
}
.atlyn-marimekko .cell-label,
.atlyn-marimekko .cell-name {
  fill: #172b3a;
  stroke: #fff;
  stroke-width: 2px;
  paint-order: stroke;
  stroke-linejoin: round;
}
.atlyn-marimekko .value-label {
  font-weight: 650;
  font-size: 1.12em;
}
.atlyn-marimekko .cell-name {
  font-size: 0.95em;
}
.atlyn-marimekko .segment-label,
.atlyn-marimekko .width-label {
  fill: var(--ink);
}
.atlyn-marimekko .segment-label {
  font-weight: 600;
}
.atlyn-marimekko .width-label {
  font-size: 11px;
}
.atlyn-marimekko .selected {
  outline: 2px solid var(--ink);
  outline-offset: -2px;
}
.atlyn-marimekko .muted {
  opacity: 0.3;
}
.atlyn-marimekko .highlight-base {
  opacity: 0.25;
}
.atlyn-marimekko .highlight-base.muted {
  opacity: 0.12;
}
.atlyn-marimekko.high-contrast .cell-label,
.atlyn-marimekko.high-contrast .cell-name {
  fill: var(--ink);
  stroke: var(--paper);
}
.atlyn-marimekko.high-contrast .selected {
  outline: 3px double var(--ink);
}
.atlyn-marimekko .table-container {
  overflow: auto;
  flex: 1 1 0;
  min-height: 0;
}
.atlyn-marimekko .table-container:not(.sr-only) ~ .plot-container {
  flex-basis: 35%;
}
.atlyn-marimekko .pager {
  padding: 4px 0;
  position: sticky;
  top: 0;
  background: var(--paper);
}
.atlyn-marimekko table {
  border-collapse: collapse;
  width: 100%;
  text-align: start;
}
.atlyn-marimekko caption {
  text-align: start;
  padding: 5px 0;
  font-size: 11px;
}
.atlyn-marimekko th,
.atlyn-marimekko td {
  border-bottom: 1px solid currentColor;
  padding: 5px;
  vertical-align: top;
}
.atlyn-marimekko th {
  text-align: start;
}
.atlyn-marimekko .table-select {
  border: 0;
  text-align: start;
  padding: 0;
}
.atlyn-marimekko .information,
.atlyn-marimekko .onboarding {
  flex: 1 1 0;
  min-height: 0;
  overflow: auto;
}
.atlyn-marimekko .information > * {
  margin-bottom: 10px;
}
.atlyn-marimekko .onboarding {
  border: 1px solid currentColor;
  border-radius: 6px;
  padding: 14px;
}
.atlyn-marimekko .onboarding p {
  margin-top: 8px;
}
.atlyn-marimekko .notices {
  white-space: pre-wrap;
  font-size: 11px;
}
.atlyn-marimekko .small-state {
  overflow: auto;
  font-size: 11px;
}
.atlyn-marimekko .sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
}
.atlyn-marimekko.compact {
  padding: 8px;
  gap: 4px;
}
.atlyn-marimekko.compact .title {
  font-size: 13px;
}
.atlyn-marimekko.compact .header button {
  padding: 3px 5px;
  font-size: 11px;
  min-height: 26px;
}
.atlyn-marimekko.compact .legend {
  flex-wrap: nowrap;
  max-height: 42px;
  overflow-y: hidden;
  scrollbar-width: thin;
}
.atlyn-marimekko.compact .legend-item {
  flex-shrink: 0;
  font-size: 11px;
}
.atlyn-marimekko.compact .legend-item span {
  max-width: 130px;
}
.atlyn-marimekko.compact .status {
  max-height: 42px;
}
.atlyn-marimekko.compact .total {
  font-size: 11px;
}
.atlyn-marimekko.compact .width-label {
  font-size: 10px;
}
.atlyn-marimekko.compact .segment-label {
  font-size: 11px;
}
.atlyn-marimekko.compact .pager {
  position: static;
}
.atlyn-marimekko.no-geometry .status {
  max-height: none;
  flex: 0 1 auto;
}
.atlyn-marimekko.no-geometry.table-open .status {
  max-height: min(26%, 42px);
}
.atlyn-marimekko.micro .header {
  justify-content: flex-start;
}
.atlyn-marimekko.micro .controls {
  gap: 3px;
}
.atlyn-marimekko.micro .status {
  max-height: 30px;
}
.atlyn-marimekko.micro .encoding {
  display: none;
}
